mapper.update:
UPDATE menu_item SET updated_at = NOW()
, name = #{name}
, description = #{description}
, section_id = #{sectionId}
, sort_order = #{sortOrder}
, image_id = #{imageId}
, image_status = #{imageStatus}
, needs_confirmation = #{needsConfirmation}
WHERE id = #{id} AND is_deleted = 0

mapper.select:
SELECT mi.name AS name, COUNT(*) AS cnt
FROM menu_item mi
INNER JOIN menu_recipe r ON r.id = mi.recipe_id AND r.is_deleted = 0
WHERE mi.is_deleted = 0 AND r.group_id = #{groupId}
GROUP BY mi.name ORDER BY cnt DESC
LIMIT #{limit}
